#include "power_saving_view.h"
#include <imgui.h>
#include <algorithm>
#include <cstdio>
namespace druta::ui {
std::optional<uint32_t> parse_power_saving_us(const std::string& text){const auto begin=text.find_first_not_of(" \t\r\n"),end=text.find_last_not_of(" \t\r\n");if(begin==std::string::npos)return {};uint64_t value=0;for(size_t n=begin;n<=end;++n){if(text[n]<'0'||text[n]>'9')return {};value=value*10+static_cast<uint32_t>(text[n]-'0');if(value>UINT32_MAX)return {};}return value?std::optional<uint32_t>(static_cast<uint32_t>(value)):std::nullopt;}
void sync_power_saving_view(PowerSavingViewState& state,const PowerSavingData* data,uint64_t generation){if(!state.initialized||state.generation!=generation){state={};state.initialized=true;state.generation=generation;}if(!data)return;for(const auto& row:data->rows){auto it=std::find_if(state.drafts.begin(),state.drafts.end(),[&](const auto& d){return d.key==row.key;});if(it==state.drafts.end()){state.drafts.push_back({});it=state.drafts.end()-1;it->key=row.key;}if(!it->dirty&&!row.stale){it->binding=row.binding;it->expected=row.value;if(row.value)std::snprintf(it->text.data(),it->text.size(),"%u",*row.value);}}}
bool stage_power_saving_document(PowerSavingViewState& state,const ProfileJson& document,const PowerSavingData& data){try{state.staged=stage_power_saving_profile(document,data);state.status="Profile staged; review and explicitly Apply";return true;}catch(const std::exception& e){state.status=e.what();return false;}}
std::vector<PowerSavingIntent> draw_power_saving_controls(PowerSavingViewState& state,const PowerSavingData* data,uint64_t generation,bool busy,bool unlocked,bool classic){(void)classic;sync_power_saving_view(state,data,generation);std::vector<PowerSavingIntent> out;ImGui::PushID("power-saving");ImGui::BeginDisabled(busy);if(ImGui::Button("Read power saving"))out.push_back({PowerSavingIntent::Operation::read,31,{},{}});ImGui::EndDisabled();
    const char* headings[]={"GR ELPG","Individual power gating","Idle thresholds (us)","Adaptive power","DIFR"};
    for(int family=0;family<5;++family){ImGui::PushID(family);if(ImGui::CollapsingHeader(headings[family],ImGuiTreeNodeFlags_DefaultOpen)&&data){for(const auto& row:data->rows){if(static_cast<int>(row.key.family)!=family)continue;auto draft=std::find_if(state.drafts.begin(),state.drafts.end(),[&](const auto& d){return d.key==row.key;});if(draft==state.drafts.end())continue;ImGui::PushID(static_cast<int>(row.key.index));ImGui::TextWrapped("%s%s",row.label.c_str(),row.stale?" [stale]":"");
        if(row.key.family==PowerSavingFamily::idle_threshold){if(!row.binding.empty())ImGui::Text("Raw %u / %u; applied %u / %u us",row.raw_first,row.raw_second,row.scaled_first,row.scaled_second);else ImGui::TextDisabled("Threshold readings unavailable");ImGui::SetNextItemWidth(140);if(ImGui::InputText("Request us",draft->text.data(),draft->text.size()))draft->dirty=true;const auto value=parse_power_saving_us(draft->text.data());ImGui::SameLine();ImGui::BeginDisabled(busy||!unlocked||!row.writable||row.stale||!value||!data||data->recovery_pending||(value&&*value>row.maximum_us));if(ImGui::Button("Apply")){out.push_back({PowerSavingIntent::Operation::apply,31,{{row.key,*value,draft->binding,draft->expected}}, {}});draft->dirty=false;}ImGui::EndDisabled();}
        else {if(row.aggregate_enabled)ImGui::Text("Aggregate: %s",*row.aggregate_enabled?"enabled":"disabled");if(row.key.family==PowerSavingFamily::adaptive)ImGui::Text("This app: %s",row.value?(*row.value?"Allow":"Disable"):"unknown");else ImGui::Text("This app: %s",row.uncertain?"uncertain":row.owned?"holds disable":"released");const bool adaptive=row.key.family==PowerSavingFamily::adaptive;ImGui::BeginDisabled(busy||!unlocked||(!adaptive&&(!row.writable||row.stale||data->recovery_pending))||(adaptive&&!row.supported));if(ImGui::Button(adaptive?"Disable":"Hold disable"))out.push_back({PowerSavingIntent::Operation::apply,31,{{row.key,adaptive?0u:1u,row.binding,row.value}}, {}});ImGui::EndDisabled();ImGui::SameLine();ImGui::BeginDisabled(busy||!unlocked||(adaptive?!row.supported:(!row.owned||row.uncertain)));if(ImGui::Button(adaptive?"Allow":"Release"))out.push_back({PowerSavingIntent::Operation::apply,31,{{row.key,adaptive?1u:0u,row.binding,row.value}}, {}});ImGui::EndDisabled();}
        ImGui::SameLine();ImGui::BeginDisabled(busy||!unlocked||!row.initial||row.stale||!row.writable||data->recovery_pending);if(ImGui::Button("Restore initial"))out.push_back({PowerSavingIntent::Operation::restore_initial,31,{}, {row.key}});ImGui::EndDisabled();ImGui::SameLine();ImGui::Checkbox("Profile",&draft->include);if(!row.message.empty())ImGui::TextWrapped("%s",row.message.c_str());ImGui::PopID();}}ImGui::PopID();}
    ImGui::BeginDisabled(busy||!unlocked||!data||!data->owned_requests);if(ImGui::Button("Release owned power-saving requests"))out.push_back({PowerSavingIntent::Operation::release_owned,31,{},{}});ImGui::EndDisabled();
    ImGui::BeginDisabled(busy||!unlocked||!data||!data->undo_available);if(ImGui::Button("Undo power-saving request"))out.push_back({PowerSavingIntent::Operation::undo,31,{},{}});ImGui::EndDisabled();ImGui::SameLine();ImGui::BeginDisabled(busy||!unlocked||!data||!data->recovery_pending);if(ImGui::Button("Recover power-saving request"))out.push_back({PowerSavingIntent::Operation::recover,31,{},{}});ImGui::EndDisabled();
    std::vector<PowerSavingKey> selection;for(const auto& d:state.drafts)if(d.include)selection.push_back(d.key);ImGui::BeginDisabled(busy||!data||selection.empty());if(ImGui::Button("Save power-saving profile"))out.push_back({PowerSavingIntent::Operation::save_profile,31,{},selection});ImGui::EndDisabled();ImGui::SameLine();ImGui::BeginDisabled(busy);if(ImGui::Button("Load power-saving profile"))out.push_back({PowerSavingIntent::Operation::load_profile,31,{},{}});ImGui::EndDisabled();
    if(!state.staged.empty()){ImGui::TextDisabled("Staged requests apply individually; Undo restores the previous edit");for(size_t n=0;n<state.staged.size();++n){const auto& r=state.staged[n];ImGui::PushID(static_cast<int>(n));ImGui::Text("Staged family %u / controller %u: %u",static_cast<uint32_t>(r.key.family),r.key.index,r.value);ImGui::SameLine();ImGui::BeginDisabled(busy||!unlocked||!data||(data->recovery_pending&&r.key.family!=PowerSavingFamily::adaptive));if(ImGui::Button("Apply staged request"))out.push_back({PowerSavingIntent::Operation::apply,31,{r},{}});ImGui::EndDisabled();ImGui::PopID();}if(ImGui::Button("Discard staged power-saving profile"))state.staged.clear();}
    if(data&&!data->message.empty())ImGui::TextWrapped("%s",data->message.c_str());if(!state.status.empty())ImGui::TextWrapped("%s",state.status.c_str());if(ImGui::CollapsingHeader("Power-saving details"))ImGui::TextWrapped("Requests last only this session. Initial means the first qualified request, never factory defaults. Aggregate enabled state is not request ownership or physical residency. Adaptive Allow does not restore idle thresholds. Counted operations with uncertain outcomes cannot be blindly repeated. Profiles contain explicit values and load as drafts; nothing is reapplied at startup or after driver reset.");ImGui::PopID();return out;}
}
